//go:build darwin || linux

package cli

import (
	"context"
	"errors"
	"io"
	"os"
	"reflect"
	"testing"
	"time"

	"github.com/creack/pty"
	"github.com/entireio/cli/internal/procsignal"
	"golang.org/x/sys/unix"
